#include "gitmodel.h"
#include "../src/namecodec.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
int git_oid_valid(const char *p){size_t n=strlen(p);if(n!=40&&n!=64)return 0;for(size_t i=0;i<n;i++)if(!((p[i]>='0'&&p[i]<='9')||(p[i]>='a'&&p[i]<='f')))return 0;return 1;}
int git_path_safe(const wchar_t *p){if(!p||!*p||*p==L'\\')return 0;while(*p){const wchar_t *end=wcschr(p,L'\\');size_t n=end?(size_t)(end-p):wcslen(p);if(!n||(n==1&&p[0]==L'.')||(n==2&&p[0]==L'.'&&p[1]==L'.'))return 0;for(size_t i=0;i<n;i++)if(p[i]==L':'||p[i]==L'/')return 0;if(!end)return 1;p=end+1;}return 0;}
void git_model_free(git_model *m){for(uint32_t i=0;i<m->count;i++){free(m->entries[i].path);free(m->entries[i].original);}free(m->entries);free(m->root);memset(m,0,sizeof *m);}
static wchar_t *decode(const uint8_t *p,size_t n,int native,int path){if(!n||n>32768)return NULL;wchar_t *out=calloc(n*2+1,2);if(!out)return NULL;if(native){if(!fpe_lx_from_bytes(p,n,out,n*2+1,1,path,NULL)){free(out);return NULL;}}else{if(memchr(p,0,n)){free(out);return NULL;}int k=MultiByteToWideChar(CP_UTF8,MB_ERR_INVALID_CHARS,(const char*)p,(int)n,out,(int)(n*2));if(!k){free(out);return NULL;}out[k]=0;if(path)for(int i=0;i<k;i++)if(out[i]==L'/')out[i]=L'\\';}return out;}
static int entry_cmp(const void *a,const void *b){return wcscmp(((const git_entry*)a)->path,((const git_entry*)b)->path);}
static int status_char(char c){return c=='.'||strchr("MADRCUT",c)!=NULL;}
DWORD git_parse_status(git_model *m,const wchar_t *root,const uint8_t *raw,size_t n,int native){git_model result={.native=(uint32_t)native};DWORD error=0;if(!root||!*root||n>2*1024*1024){error=ERROR_INVALID_DATA;goto done;}result.root=_wcsdup(root);if(!result.root){error=ERROR_NOT_ENOUGH_MEMORY;goto done;}size_t at=0;
 while(at<n){const uint8_t *z=memchr(raw+at,0,n-at);if(!z){error=ERROR_INVALID_DATA;break;}size_t length=z-(raw+at);const uint8_t *record=raw+at;at+=length+1;if(!length){error=ERROR_INVALID_DATA;break;}
  if(record[0]=='#'){char *line=malloc(length+1);if(!line){error=ERROR_NOT_ENOUGH_MEMORY;break;}memcpy(line,record,length);line[length]=0;const char *value=NULL;wchar_t *target=NULL;if(!strncmp(line,"# branch.head ",14)){value=line+14;target=result.branch;}else if(!strncmp(line,"# branch.upstream ",18)){value=line+18;target=result.upstream;}else if(!strncmp(line,"# branch.oid ",13)){if(strcmp(line+13,"(initial)")&& !git_oid_valid(line+13))error=ERROR_INVALID_DATA;else strncpy(result.oid,line+13,64);}else if(!strncmp(line,"# branch.ab ",12)){int used=0;if(sscanf(line+12,"+%d -%d%n",&result.ahead,&result.behind,&used)!=2||result.ahead<0||result.behind<0||line[12+used])error=ERROR_INVALID_DATA;else result.tracking=1;}
   if(target){wchar_t *decoded=decode((const uint8_t*)value,strlen(value),native,0);if(!decoded||wcslen(decoded)>255)error=ERROR_INVALID_DATA;else wcscpy(target,decoded);free(decoded);}free(line);if(error)break;continue;}
  if(result.count>=GIT_ENTRIES){error=ERROR_BUFFER_OVERFLOW;break;}git_entry e={0};e.meta.kind=record[0];size_t fields=record[0]=='1'?8:record[0]=='2'?9:record[0]=='u'?10:record[0]=='?'?1:0;if(!fields){error=ERROR_INVALID_DATA;break;}
  char *tokens[10]={0};uint8_t *copy=malloc(length+1);if(!copy){error=ERROR_NOT_ENOUGH_MEMORY;break;}memcpy(copy,record,length);copy[length]=0;char *p=(char*)copy;int ok=1;for(size_t i=0;i<fields;i++){tokens[i]=p;char *space=strchr(p,' ');if(!space){ok=0;break;}*space=0;p=space+1;}
  if(!ok||!*p){free(copy);error=ERROR_INVALID_DATA;break;}e.path=decode((uint8_t*)p,strlen(p),native,1);
  if(record[0]=='?'){e.meta.x=e.meta.y='?';}
  else{if(strlen(tokens[1])!=2||!status_char(tokens[1][0])||!status_char(tokens[1][1])||strlen(tokens[2])!=4)ok=0;else{e.meta.x=tokens[1][0];e.meta.y=tokens[1][1];}for(int i=0;i<3;i++){char *end;unsigned long v=strtoul(tokens[3+i],&end,8);if(*end||!tokens[3+i][0]||v>0177777)ok=0;e.meta.mode[i]=(uint32_t)v;}
   if(record[0]!='u'){if(!git_oid_valid(tokens[6])||!git_oid_valid(tokens[7]))ok=0;else{strcpy(e.meta.head,tokens[6]);strcpy(e.meta.index,tokens[7]);}}
  }free(copy);
  if(record[0]=='2'){if(at>=n){ok=0;}else{z=memchr(raw+at,0,n-at);if(!z)ok=0;else{e.original=decode(raw+at,z-(raw+at),native,1);at=(size_t)(z-raw)+1;if(!e.original||!git_path_safe(e.original))ok=0;}}}
  if(!e.path||!git_path_safe(e.path))ok=0;if(e.path)result.names+=(wcslen(e.path)+1)*2;if(e.original)result.names+=(wcslen(e.original)+1)*2;
  if(!ok||result.names>GIT_NAMES){free(e.path);free(e.original);error=ok?ERROR_BUFFER_OVERFLOW:ERROR_INVALID_DATA;break;}
  if(result.count==result.capacity){uint32_t cap=result.capacity?result.capacity*2:128;git_entry *entries=realloc(result.entries,(size_t)cap*sizeof *entries);if(!entries){free(e.path);free(e.original);error=ERROR_NOT_ENOUGH_MEMORY;break;}result.entries=entries;result.capacity=cap;}result.entries[result.count++]=e;
 }
 if(!error&&(!result.oid[0]||!result.branch[0]))error=ERROR_INVALID_DATA;
 if(!error){qsort(result.entries,result.count,sizeof *result.entries,entry_cmp);for(uint32_t i=1;i<result.count;i++)if(!wcscmp(result.entries[i-1].path,result.entries[i].path)){error=ERROR_INVALID_DATA;break;}}
done:git_model_free(m);if(error){git_model_free(&result);m->error=error;}else *m=result;return error;}
const git_entry *git_find(const git_model *m,const wchar_t *path){uint32_t a=0,b=m->count;while(a<b){uint32_t mid=a+(b-a)/2;int c=wcscmp(m->entries[mid].path,path);if(c<0)a=mid+1;else b=mid;}return a<m->count&&!wcscmp(m->entries[a].path,path)?&m->entries[a]:NULL;}
int git_badge(const git_model *m,const wchar_t *folder,const wchar_t *name,int directory,wchar_t out[4]){out[0]=0;if(!m->root||!folder||!name)return 0;const wchar_t *root=m->root;if(m->native){const wchar_t *prefixes[]={L"\\\\wsl.localhost\\",L"\\\\wsl$\\"};for(int i=0;i<2;i++){size_t k=wcslen(prefixes[i]);if(!_wcsnicmp(root,prefixes[i],k)){root+=k-1;break;}}int found=0;for(int i=0;i<2;i++){size_t k=wcslen(prefixes[i]);if(!_wcsnicmp(folder,prefixes[i],k)){folder+=k-1;found=1;break;}}if(!found)return 0;}size_t n=wcslen(root),f=wcslen(folder);while(n>3&&root[n-1]==L'\\')n--;if(f<n||(m->native?wcsncmp(folder,root,n):_wcsnicmp(folder,root,n))||(f>n&&folder[n]!=L'\\'&&root[n-1]!=L'\\'))return 0;const wchar_t *part=folder+n;while(*part==L'\\')part++;size_t needed=wcslen(part)+wcslen(name)+3;if(needed>32768)return 0;wchar_t relative[32768];swprintf(relative,32768,L"%ls%ls%ls",part,*part?L"\\":L"",name);const git_entry *e=git_find(m,relative);if(e){out[0]=e->meta.x;out[1]=e->meta.y;out[2]=0;return 1;}if(directory){size_t len=wcslen(relative);relative[len++]=L'\\';relative[len]=0;uint32_t a=0,b=m->count;while(a<b){uint32_t mid=a+(b-a)/2;if(wcscmp(m->entries[mid].path,relative)<0)a=mid+1;else b=mid;}if(a<m->count&&!wcsncmp(m->entries[a].path,relative,len)){wcscpy(out,L"*");return 1;}}return 0;}
